  check('counter restored after reload', s.status === '1 of 2 done', s.status);

  await remove(0);
  s = await snapshot();
  check('delete removes the right item', s.count === 1 && s.texts[0] === 'Walk dog' && s.stored.length === 1 && s.stored[0].text === 'Walk dog', s);

  await remove(0);
  s = await snapshot();
