const results = [];
function check(name, cond, detail) {
  results.push({ name, pass: !!cond, detail: cond ? undefined : detail });
}

function cleanup() {
  chrome.kill('SIGTERM');
  try {
    fs.rmSync(PROFILE, { recursive: true, force: true, maxRetries: 10, retryDelay: 200 });
  } catch (e) {}
}

async function wsUrl() {
  for (let i = 0; i < 150; i++) {
    try {
      const list = await (await fetch('http://127.0.0.1:' + PORT + '/json/list')).json();
      const page = list.find((t) => t.type === 'page' && t.url.startsWith('file://'));
      if (page) return page.webSocketDebuggerUrl;
    } catch (e) {}
    await sleep(100);
  }
  throw new Error('no devtools page target');
}

async function main() {
  const ws = new WebSocket(await wsUrl());
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = () => rej(new Error('ws error')); });

  let seq = 0;
  const pending = new Map();
  const events = new Map();
  const exceptions = [];

  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
      else p.resolve(msg.result);
      return;
    }
    if (msg.method === 'Runtime.exceptionThrown') exceptions.push(msg.params.exceptionDetails.text);
    (events.get(msg.method) || []).forEach((fn) => fn(msg.params));
  });

  function send(method, params) {
    const id = ++seq;
    ws.send(JSON.stringify({ id, method, params: params || {} }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evaluate(expression) {
    const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error('page exception: ' + JSON.stringify(r.exceptionDetails));
    return r.result.value;
  }

  let loadWaiter = null;
  events.set('Page.loadEventFired', [() => { const w = loadWaiter; loadWaiter = null; if (w) w(); }]);

  await send('Page.enable');
  await send('Runtime.enable');

  async function reload() {
    const loaded = new Promise((res) => { loadWaiter = res; });
    await send('Page.reload', { ignoreCache: true });
    await Promise.race([loaded, sleep(5000)]);
    for (let i = 0; i < 60; i++) {
      const ready = await evaluate("document.readyState === 'complete' && !!document.getElementById('todo-list')");
